package br.com.brindespro.pricing;
import br.com.brindespro.catalog.*;import br.com.brindespro.admin.*;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service public class PricingService {
  private final ProductRepository products;private final VariantRepository variants;private final PrintingPositionRepository positions;private final ProductionDeadlineRepository deadlines;private final EngravingOptionRepository engravings;private final KitRepository kits;
  public PricingService(ProductRepository products,VariantRepository variants,PrintingPositionRepository positions,ProductionDeadlineRepository deadlines,EngravingOptionRepository engravings,KitRepository kits){this.products=products;this.variants=variants;this.positions=positions;this.deadlines=deadlines;this.engravings=engravings;this.kits=kits;}
  public record Request(@NotNull Long productId,@NotNull Long variantId,@Min(1) int quantity,@NotBlank String engraving,@NotBlank String printingPosition,@NotBlank String deadline,Long kitId,Long logoFileId,String logoToken,Preview preview){}
  public record Preview(BigDecimal x,BigDecimal y,BigDecimal scale){}
  public record Result(BigDecimal baseUnitPrice,BigDecimal unitPrice,BigDecimal subtotal,BigDecimal surcharge,BigDecimal total,int quantity,String tierLabel,String currency,Product product,ProductVariant variant){}
  public Result calculate(Request request){Product p=products.findById(request.productId()).filter(v->v.active).orElseThrow(()->new IllegalArgumentException("Produto indisponível."));ProductVariant variant=variants.findById(request.variantId()).filter(v->v.product.id.equals(p.id)).orElseThrow(()->new IllegalArgumentException("Cor inválida para o produto."));if(request.quantity()<p.minQuantity)throw new IllegalArgumentException("Quantidade abaixo do mínimo do produto.");if(Arrays.stream(p.engravingOptions.split(",")).map(String::trim).noneMatch(request.engraving()::equals))throw new IllegalArgumentException("Gravação incompatível com o produto.");EngravingOption engraving=engravings.findByNameAndActiveTrue(request.engraving()).orElseThrow(()->new IllegalArgumentException("Gravação indisponível."));PrintingPosition position=positions.findByNameAndActiveTrue(request.printingPosition()).orElseThrow(()->new IllegalArgumentException("Posição indisponível."));ProductionDeadline deadline=deadlines.findByNameAndActiveTrue(request.deadline()).orElseThrow(()->new IllegalArgumentException("Prazo indisponível."));PricingTier tier=p.tiers.stream().filter(t->request.quantity()>=t.minQuantity&&(t.maxQuantity==null||request.quantity()<=t.maxQuantity)).findFirst().orElseThrow(()->new IllegalArgumentException("Não há faixa de preço para essa quantidade."));BigDecimal discount=BigDecimal.ZERO;if(request.kitId()!=null){Kit kit=kits.findById(request.kitId()).filter(k->k.active&&k.items.stream().anyMatch(i->i.product.id.equals(p.id))).orElseThrow(()->new IllegalArgumentException("Produto não pertence ao kit selecionado."));discount=kit.discountPercent;}BigDecimal base=tier.unitPrice;BigDecimal percent=engraving.percent.add(position.percent).add(deadline.percent);BigDecimal unit=base.multiply(BigDecimal.ONE.add(percent)).multiply(BigDecimal.ONE.subtract(discount)).setScale(2,RoundingMode.HALF_UP);BigDecimal subtotal=base.multiply(BigDecimal.valueOf(request.quantity())).setScale(2,RoundingMode.HALF_UP);BigDecimal total=unit.multiply(BigDecimal.valueOf(request.quantity())).setScale(2,RoundingMode.HALF_UP);return new Result(base,unit,subtotal,total.subtract(subtotal),total,request.quantity(),tier.minQuantity+"-"+(tier.maxQuantity==null?"∞":tier.maxQuantity),"BRL",p,variant);}
}
